#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_scale;
uniform float amzp_phase;
uniform float amzp_radius;
uniform float amzp_feather;
layout(color) uniform half4 amzp_color;
layout(color) uniform half4 amzp_color2;
uniform float amzp_density;
uniform float2 amzp_position;
uniform float amzp_fill;
uniform float amzp_alpha;
uniform float amzp_blendMode;
uniform float amzp_seed;
uniform float amzp_slack;
        float random (in float2 st) {
            return fract(sin(dot(st.xy,
                                 float2(12.9898,78.233)))*
                43758.5453123);
        }
        float noise (float2 st) {
            float2 i = floor(st);
            float2 f = fract(st);
            float a = random(i);
            float b = random(i + float2(1.0, 0.0));
            float c = random(i + float2(0.0, 1.0));
            float d = random(i + float2(1.0, 1.0));
            float2 u = f * f * (3.0 - 2.0 * f);
            return mix(a, b, u.x) +
                    (c - a)* u.y * (1.0 - u.x) +
                    (d - b) * u.x * u.y;
        }
        float fbm (float2 st, float2 parallax, int octaveCount, float intens) {
            float value = 0.;
            float amplitude = 0.5;
            float frequency = 0.;
            for (int i = 0; i < octaveCount; i++) {
                value += amplitude * noise(st);
                st *= 2.0;
                st += parallax;
                amplitude *= intens;
            }
            return value;
        }
        float2 rand2v(float2 co) {
            return float2(noise(co),noise(co+float2(613.312,736.019)));
        }
        void amzRender() {
            float4 texColor = amzTexture(0,amzScreenNorm());
            float2 st = amzLayerNorm().st;
            st.x *= layer.x/layer.y;
            st -= float2(0.5,0.5);
            st -= (amzp_position*float2(1.0,-1.0)/1000.0);
            st /= (amzp_scale*0.07);
            float2 tile = floor(st);
            float2 tpart = fract(st);
            float maxDist = 100.0;
            float2 nearestTile = float2(0.0,0.0);
            float nearest_k = 0.;
            int densitySteps = int(max(1.0,amzp_density-10.0));
            float threshold = min(1.0,amzp_density/11.0);
            float actualPhase = amzp_phase * 6.28318;
            for( int i=-1; i<=1; i++ ) {
                for( int j=-1; j<=1; j++ ) {
                    float2 checkTileOffs = float2(float(i),float(j));
                    for( int k=0; k<densitySteps; k++ ) {
                        float2 p = rand2v(tile + float2(523.135,621.265)*float(k) + checkTileOffs + float2(123.215,272.055)*amzp_seed);
                        p = 0.5 + (0.5*sin(actualPhase + 6.2831*p)*max(0.00001,amzp_slack));
                        float dist = length(checkTileOffs + p - tpart);
                        float2 tileId = checkTileOffs + tile;
                        float flk = float(k);
                        float ck = random(tileId + float2(flk,-flk) + float2(541.117,163.713)*(amzp_seed+0.1));
                        if( dist < maxDist && ck<=threshold ) {
                            maxDist = dist;
                            nearest_k = float(k);
                            nearestTile = tileId;
                        }
                    }
                }
            }
            float colorPct = random(nearestTile + float2(nearest_k,-nearest_k) + float2(721.117,433.215)*amzp_seed);
            float intensity = smoothstep(1.0-amzp_radius,1.0-(amzp_radius*(1.0-amzp_feather)),1.-maxDist);
            float4 over = texColor * amzp_fill;
            float4 rcolor = mix(amzp_color,amzp_color2,colorPct)*intensity*texColor.a;
            float4 result;
            if( int(amzp_blendMode)==1 ) {
                result = float4((texColor.rgb/texColor.a)*(rcolor.rgb/rcolor.a),1.0) * rcolor.a * texColor.a;
                result = clamp(result,0.0,1.0);
                result = result+(over*(1.0-result.a));
                result = clamp(result,0.0,1.0);
            } else if( int(amzp_blendMode)==2 ) {
                result = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-(rcolor.rgb/rcolor.a))),1.0) * rcolor.a * texColor.a;
                result = clamp(result,0.0,1.0);
                result = result+(over*(1.0-result.a));
                result = clamp(result,0.0,1.0);
            } else {
                result = rcolor+(over*(1.0-rcolor.a));
            }
            amzOutput = mix(over,result,amzp_alpha);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
